#include <bits/stdc++.h>
using namespace std;
#define int long long

const int MAX_VAL = 100000 + 5;
const int MOD_VAL = 1000000007;
int lookup[17];

int computeCost(int val, int level) {
    if (level == 0) {
        return (val == 0) ? 0 : MOD_VAL;
    }
    int count = val / lookup[level];
    if (val % lookup[level] == 0) return level * count;
    int costOption1 = computeCost(abs(val - lookup[level] * (count + 1)), level - 1) + level;
    int costOption2 = computeCost(val - lookup[level] * count, level - 1);
    return min(level * (count + 1) + costOption1 - level, level * count + costOption2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    lookup[1] = 1;
    for (int i = 2; i < 17; ++i) {
        lookup[i] = lookup[i - 1] * 10 + 1;
    }
    int val; cin >> val;
    cout << computeCost(val, 16) << "\n";
    return 0;
}
